import copy
from lxml import etree


class NetconfMessage(object):
    """
    Base class for NETCONF messages.
    """

    def __init__(self, string, **kwargs):
        """
        Create a NETCONF message.

        :param bytes string: XML encoded NETCONF message (one line)
        """
        super(NetconfMessage, self).__init__(**kwargs)
        self._full_xml = etree.fromstring(
            string,
            parser=etree.XMLParser(remove_blank_text=True))
        self._xml = self._namespaces_removed(self._full_xml)

    @staticmethod
    def _namespaces_removed(xml):
        xml = copy.deepcopy(xml)
        for element in xml.getiterator():
            element.tag = etree.QName(element).localname
            for attribute_name, attribute_value in element.items():
                attribute_qname = etree.QName(attribute_name)
                if attribute_qname.namespace:
                    del element.attrib[attribute_name]
                    element.attrib[attribute_qname.localname] = attribute_value
        etree.cleanup_namespaces(xml)
        return xml

    @property
    def type(self):
        """
        NETCONF message type as string.
        """
        return self.__class__.__name__

    def __str__(self):
        """
        String representation (one line) of XML encoded NETCONF message.
        """
        return etree.tostring(self._full_xml, encoding="unicode")

    @property
    def full_xml(self):
        """
        XML representation of NETCONF message including namespaces.
        """
        return self._full_xml

    @property
    def xml(self):
        """
        XML representation of NETCONF message without namespaces.
        """
        return self._xml


class Rpc(NetconfMessage):
    """
    Base class for NETCONF RPC requests/replies.
    """

    @property
    def id(self):
        """
        Message ID of RPC request/reply.
        """
        return self.xml.xpath("//@message-id")[0]


class RpcRequest(Rpc):
    """
    NETCONF RPC request from client.
    """

    @property
    def operation(self):
        """
        Operation type of RPC request.
        """
        return self.xml.xpath("*[1]")[0].tag


class RpcReply(Rpc):
    """
    NETCONF RPC reply from server.
    """


class Notification(NetconfMessage):
    """
    NETCONF notification from server.
    """


class HelloRequest(NetconfMessage):
    """
    NETCONF hello request from client.
    """


class HelloReply(NetconfMessage):
    """
    NETCONF hello reply from server.
    """
